<template><section class="v2-page patient-readable summary-page"><header class="summary-celebration"><CheckCircle2 :size="50"/><p class="v2-context">今天完成了</p><h1>这次训练已经保存</h1><p>完成情况、使用提示和技术问题都已分别记录。</p></header><div v-if="loading" class="v2-state">正在整理总结…</div><div v-else-if="error" class="v2-state v2-state-error"><strong>总结暂时没有准备好</strong><span>{{ error }}</span></div><template v-else-if="summary"><section class="summary-facts"><div v-for="item in factItems" :key="item.label"><strong>{{ item.value }}</strong><span>{{ item.label }}</span></div></section><section class="v2-section-block"><p class="v2-section-label">今天的观察</p><h2>做得好的地方</h2><ul class="patient-observations"><li v-for="item in summary.patient_observations" :key="item">{{ item }}</li></ul></section><section class="v2-action-sheet"><div><p class="v2-section-label">下一次</p><h2>继续按计划练习</h2><p>{{ summary.next_training_focus }}</p></div><RouterLink class="v2-button primary" to="/progress">看看我的进展</RouterLink></section></template></section></template>
<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import { CheckCircle2 } from 'lucide-vue-next';import { v2Api } from '@/api/v2';import { toUserMessage } from '@/utils/errors';const route=useRoute();const summary=ref<any>(null);const loading=ref(true);const error=ref('');const factItems=computed(()=>summary.value?[{label:'计划练习',value:summary.value.facts.planned_exercises},{label:'完成',value:summary.value.facts.completed_exercises},{label:'使用提示完成',value:summary.value.facts.prompted_completed_exercises},{label:'技术原因未评分',value:summary.value.facts.technical_invalid_exercises}]:[]);onMounted(async()=>{try{summary.value=await v2Api.summary(String(route.params.sessionId))}catch(err){error.value=toUserMessage(err,'请稍后从训练记录中查看。')}finally{loading.value=false}});</script>
